  const l = c.querySelector('.ld-l'); if (l) l.textContent = line;
  const b = c.querySelector('.ld-b'); if (b && frac != null) { b.classList.remove('ind'); b.firstChild.style.width = (100 * Math.max(0, Math.min(1, frac))).toFixed(1) + '%'; }
