  const hashAll = (s) => { let h = 5381, g = 52711; for (let i = 0; i < s.length; i++) { const c = s.charCodeAt(i); h = ((h << 5) + h + c) | 0; g = ((g << 5) + g + c) | 0; } return (h >>> 0).toString(36) + (g >>> 0).toString(36) + s.length.toString(36); };
