// before come along once)
const notesKey = (boss) => 'wla-rnote|' + boss;
const nmSetOf = (t) => noteNames(t).map((x) => x.toLowerCase()).sort().join('|');
function notesOf(boss) {
  let o = null; try { o = JSON.parse(store.get(notesKey(boss)) || 'null'); } catch (e) { o = null; }
  if (!o || !Array.isArray(o.list)) { o = { list: [], pick: 'auto' };
    try { const old = []; for (let i = 0; i < localStorage.length; i++) { const k = localStorage.key(i); if (k && ((k.startsWith('wla-lognote-') && k.endsWith('|' + boss)) || k === 'wla-notes-' + boss)) old.push(k); }
      for (const k of old) { const x = JSON.parse(localStorage.getItem(k) || 'null'); for (const n of (x && x.list) || []) if (!o.list.some((y) => noteNorm(y.text) === noteNorm(n.text))) o.list.push(n); }
      if (o.list.length) notesSave(boss, o); old.forEach((k) => localStorage.removeItem(k)); } catch (e) { /* storage off */ } }
  return o;
}
// (one note per roster (your call, Oct 20): two notes for the exact same players keep the newest)
function notesSave(boss, o) { const by = new Map(); for (const n of o.list.slice().sort((a, b) => (b.saved || 0) - (a.saved || 0))) { const k = n.example ? 'ex' : nmSetOf(n.text) + (/^[^\n]*difficulty:\s*(heroic|15)\b/i.test(String(n.text)) ? '|H' : '|M'); /* (per difficulty too, Oct 24) */ if (!by.has(k)) by.set(k, n); }
  o.list = [...by.values()]; o.pick = 'auto'; o.byPull = {}; try { if (o.list.length) store.set(notesKey(boss), JSON.stringify(o)); else localStorage.removeItem(notesKey(boss)); } catch (e) { /* storage off */ } }
// (a note's roster match: how many of the pull's players it names, as whole words)
const noteHas = (text, name) => new RegExp('(^|[^\\p{L}])' + name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '($|[^\\p{L}])', 'iu').test(text);
const noteScore = (text, rep) => [...rep.players.values()].filter((p) => p.name && !/^Player-/.test(p.name) && noteHas(text, p.name.split('-')[0])).length;
// (a pull's own key, for a note picked for that one pull: the same moment histKey uses)
const pullKey = (it) => String(Math.round((it.wallMs || it.startMs || 0) / 10000));
// How well a saved note fits a pull (your note, Oct 18: match notes to pulls on their own, so nobody has to guess): the
// note's first line (its boss and difficulty), then its roster (the pull's players it names, less half a point for each name
// it gives who isn't there), and when two notes fit the roster about as well, the one whose jobs were done that pull
// (cooldowns on time, kicks and soaks followed), so an old and a new plan for the same players each get their own pulls.
// (nicknames (Oct 20): NSRT notes can call a player by a nickname; linked once on the swap screen, the note keeps it and the checks read the player)
const NICK_KEY = 'wla-nicks';
document.addEventListener('click', (e) => { const b = e.target.closest && e.target.closest('[data-nnew]'); if (!b || !S.rep) return; S.notePend = null; S.noteEdit = true; S.noteEditId = 'new'; S.tab = 'overview'; renderMain(); });
