    const words = body.slice(ci + 1).split(/[\s,]+/).map((w) => w.replace(/[()[\]."]/g, '')).filter((w) => w.length >= 2 && /^\p{Lu}/u.test(w));
    // (a section: the heading above the lines, else the label without its number, like "Guillotine 1" → Guillotine)
