  const secH = (x) => '<div class="ndz-ab"><div class="ndz-abh">' + iconFor(x.title) + '<b>' + esc(x.title) + '</b></div>' + x.rows.map((rw) => '<div class="ndz-abr"><span class="ndz-abl">' + esc(rw.l) + '</span><span class="ndz-abn">' + rw.n.map((n, i) => chip(n, x.kick && rw.n.length > 1 ? i + 1 : 0)).join('') + '</span></div>').join('') + '</div>';
  cds.sort((a, b) => a.ph - b.ph || a.t - b.t); if (one) cds.splice(0, cds.length, ...cds.filter((c) => c.who.some((w) => w.toLowerCase() === one.toLowerCase())));
