// (the note's cooldowns under the boss's big hits, phase by phase (Oct 23); '' when the boss has no fight clock, so the list shows)
function ndzCdTlH(boss, st, cds, byN, gapAt) { if (!boss || !cds.length) return '';
  let diff = 'Mythic'; try { const hd = (E.parseNote(st.text) || {}).header || {}; if (/heroic|15/i.test(String(hd.difficulty || ''))) diff = 'Heroic'; } catch (e) { /* (Mythic) */ }
  const SD = NDZ_CDSTART[boss] || {}, sd = SD[diff] || SD.Mythic || SD.Heroic || null, BT = NDZ_BOSSTL[boss] || {}, bt = BT[diff] || BT.Mythic || BT.Heroic || null; if (!sd && !bt) return '';
  const hits = sd ? sd.pk.map(([ph, rel, v, hit]) => ({ ph, rel, hit })) : [], moms = new Map(), at = (ph, rel, label, id) => { const k = ph + '|' + rel + '|' + label; if (!moms.has(k)) moms.set(k, { ph, rel, label, id, cds: [] }); return moms.get(k); };
  for (const c of cds) { const h = hits.filter((x) => x.ph === c.ph && c.t >= x.rel - 8 && c.t <= x.rel + 4).sort((a, b) => Math.abs(a.rel - c.t) - Math.abs(b.rel - c.t))[0];
    const m = h ? at(h.ph, Math.round(h.rel), h.hit, bt ? ndzMeta(bt, h.hit).id : 0) : ((q) => q && c.t - q.rel <= 20 ? q : at(c.ph, c.t, 'Raid cooldowns', 0))([...moms.values()].filter((x) => x.label === 'Raid cooldowns' && x.ph === c.ph && x.rel <= c.t).sort((x, y) => y.rel - x.rel)[0]); /* (merged within 20 s, Oct 23) */ for (const w of c.who) m.cds.push({ id: c.id, nm: c.nm, who: w, t: c.t, gap: gapAt.has(c.id + '|' + w.toLowerCase()) }); }
  const list = [...moms.values()].sort((a, b) => a.ph - b.ph || a.rel - b.rel), phs = [...new Set(list.map((m) => m.ph))].sort((a, b) => a - b);
  const DG = (NDZ_TLDMG[boss] || {})[diff] || (NDZ_TLDMG[boss] || {}).Mythic || null, dg = DG ? DG.ph || DG : null, all = dg ? Object.values(dg).flat().filter((v) => v > 0) : [], avg = all.length ? all.reduce((x, y) => x + y, 0) / all.length : 0; /* (why a row with no mechanic, Oct 23) */
  const ratio = (ph, t) => { const b = dg ? dg[ph] || dg[String(ph)] || [] : [], w = b.slice(Math.max(0, Math.floor((t - 1) / 2)), Math.floor((t + 10) / 2) + 1), v = w.length ? w.reduce((x, y) => x + y, 0) / w.length : 0; return avg ? v / avg : 0; };
  const onCd = (c) => typeof NDZ_ONCD === 'object' && NDZ_ONCD.has(c.nm);
  const why = (m) => { if (m.label !== 'Raid cooldowns') return ''; const r0 = Math.max(0, ...m.cds.map((c) => ratio(m.ph, c.t))), x = r0 >= 0.1 ? r0.toFixed(1) + '× the fight\'s average' : ''; /* (at each press, the worst, Oct 23) */
    if (r0 < 1.15 && m.rel <= 5) { m.label = 'Opening'; return 'Pressed early, so they\'re back sooner for the big hits'; }
    if (m.cds.every(onCd)) { m.label = 'On cooldown'; return 'Used every time it\'s back, like the top healers'; }
    if (r0 >= 1.15) { m.label = 'Heavy raid damage'; return x + ' here'; } m.label = 'Between big hits'; return x ? 'Raid damage ' + x : ''; };
  const blk = (c) => { const p = byN.get(c.who.toLowerCase()), col = p ? p.color : 'var(--gold)'; return '<span class="bjf-cd' + (c.gap ? ' warn' : '') + '" style="--cc:' + col + '" data-tt="' + esc('<b>' + esc(c.nm) + '</b> · ' + esc(c.who) + ' at ' + bjfMm(c.t) + (onCd(c) ? '<br>Used every time it\'s back.' : '') + (c.gap ? '<br>Can\'t be pressed on this character.' : '')) + '">' + spellIcon(c.id, c.nm) + '<span>' + esc(c.who) + '</span></span>'; };
  const mom = (m) => { const wy = why(m), plain = !m.id && /^(On cooldown|Heavy raid damage|Between big hits|Opening)$/.test(m.label); return '<div class="bjf-m' + (plain ? ' plain' : '') + '"><span class="bjf-t">' + bjfMm(m.rel) + '</span><span class="bjf-ic">' + (m.id ? spellIcon(m.id, m.label) : !plain ? spIc(m.label) : '<i class="bjf-dot"></i>') + '</span><div class="bjf-b"><div class="bjf-mh"><b>' + esc(m.label) + '</b>' + (wy ? '<span class="sub">' + esc(wy) + '</span>' : '') + '<span class="bjf-cds">' + m.cds.map(blk).join('') + '</span></div></div></div>'; };
  return '<div class="bjf ndz-cdtl">' + phs.map((ph) => '<div class="bjf-ph">' + bjfPh(ph) + '</div>' + list.filter((m) => m.ph === ph).map(mom).join('')).join('') + '</div>'; }
// ---- "Got an NSRT note?" (Oct 20, your idea via the Debriefing chat; test copy until you OK it) ----
