  const sugNow = () => { const keep = B.sel, keepC = B.cds, keepS = B.cdsSug, pg = B.pages[B.step - 1]; { const s0 = B.src; B.src = 'sug'; try { ndzBuildStart(B); } finally { B.src = s0; } } /* (Debrief's picks, not the plan's own, Oct 23) */ const fresh = B.sel; B.sel = keep; B.cds = keepC; B.cdsSug = keepS; const ch = []; for (const sl of pg.slots) { const k = pg.key + '|' + sl.label, was = (B.sel[k] || { n: [] }).n, now = (fresh[k] || { n: [] }).n, inn = now.filter((x) => !was.includes(x)), out = was.filter((x) => !now.includes(x)); if (was.length && (inn.length || out.length)) ch.push('<b>' + esc(sl.label) + '</b>: ' + (inn.length ? esc(andL(inn)) + ' in' : '') + (inn.length && out.length ? ', ' : '') + (out.length ? esc(andL(out)) + ' out' : '')); B.sel[k] = fresh[k]; }
    redraw(); if (ch.length) toastOk('Suggested again. ' + ch.join('; ') + '. Why each pick: under each job.', 8000); }; if ($('#ndzBSug')) $('#ndzBSug').onclick = sugNow; /* (what changed, Oct 23) */
