    const prev = wh && cdL ? (B.cds || []).find((x) => x.who === wh && ((x.id && ndzSpellNm(x.id)) || x.text) === nm && Math.abs((ndzAbsT(B, x.ph, x.t) ?? x.t) - T0) < cdL) : null;
