  const win = (c) => { const K = NDZ_CDK[nmOf(c)] || ['dr', 8]; return K[0] === 'dr' ? [c.t - 4, c.t + K[1]] : K[0] === 'heal' ? [c.t - 2, c.t + K[1]] : [c.t - 6, c.t + 4]; }; /* (a few seconds wider, so a cut pressed just after or a heal-back just before still sits on its hit, flagged) */
