document.addEventListener('click', (e) => { const B = S.noteBuild, b = B && e.target.closest && e.target.closest('[data-bcdclr]'); if (!b) return; const c = (B.cds || [])[+b.dataset.bcdclr]; if (c) { B.cds.splice(+b.dataset.bcdclr, 1); ndzPersRedraw(); } }); /* (× removes the cooldown, Oct 24) */

