const ndzSrcOk = (B, r, s) => s === 'sug' || (s === 'pulls' && !!NDZ_FILL[B.pick] && B.pick === r.item.boss && ndzPulls(r).length > 0) || (s === 'note' && ndzNoteRows(B.pick, B.noteId).some((x) => x.names && x.names.length && !x.rem));
