  const boss = B.pick, SD = NDZ_CDSTART[boss] || {}, stD = SD[B.diff] ? B.diff : SD.Mythic ? 'Mythic' : SD.Heroic ? 'Heroic' : null, st = stD ? SD[stD] : null;
