  { let s = 0; for (const p of PH) { p.len = (B.phl && +B.phl[p.ph]) || p.len; p.s = s; s += p.len; } }
  const L = Math.ceil(Math.max(...PH.map((p) => p.s + p.len))), d = new Array(L + 1).fill(0);
  for (const p of PH) { const bins = dg[p.ph] || dg[String(p.ph)] || []; for (let k = 0; k < p.len; k++) { const t = Math.floor(p.s + k); if (t <= L) d[t] = bins[Math.floor(k / 2)] || 0; } }
  const phOf = new Array(L + 1).fill(0); PH.forEach((q, i) => { for (let t = Math.max(0, Math.floor(q.s)); t < Math.min(L + 1, q.s + q.len); t++) phOf[t] = i; });
  const at = (T) => { const p = PH.filter((q) => q.s <= T + 0.01).pop() || PH[0]; return { ph: p.ph, t: Math.max(0, Math.round(T - p.s)) }; };
  const mm = (T) => Math.floor(T / 60) + ':' + String(Math.round(T % 60)).padStart(2, '0'), lab = (T) => { const q = at(T); return (q.ph % 1 ? 'Int' : 'P' + q.ph) + ' ' + mm(q.t); };
