  for (const p of pr.players.values()) { const t = ndzTalOf(p.name, p.specId); if (!t) continue; const T = NDZ_TALC[+p.specId][1];
    for (let i = have.length - 1; i >= 0; i--) if (have[i].who === p.name && T.some((x) => x[0] === have[i].n || (x[0] === 'Restoral' && have[i].n === 'Revival'))) have.splice(i, 1);
    const id = (T.find((x) => x[0] === t.pick) || [])[1]; add(p.name, t.pick, id); }
  if (!have.length) return null;
