  const HB = (NDZ_CDHAB && NDZ_CDHAB[boss]) || {}, habit = (n, T) => { let b = 0; for (const [ph, rel, sh] of HB[n] || []) { const p = PH.find((q) => q.ph === ph); if (p && Math.abs(p.s + rel - T) <= 10) b = Math.max(b, sh); } return b; };
  // (spacing: a holder's next press only once it's back, +15 s when a phase change sits between; the same cooldown from two players apart)
  const placed = [], gapOk = (h, a, b) => { const x = Math.min(a, b), y = Math.max(a, b); return y - x >= h.cd + (phOf[Math.min(L, x)] !== phOf[Math.min(L, y)] ? 5 : 0); }; /* (5 s spare across a phase change: phases come from the fastest kills, and a slower raid's run longer) */
  const free = (h, t) => placed.every((o) => (o.h !== h || gapOk(h, o.t, t)) && !(NDZ_NOSTACK.has(h.n) && o.h.n === h.n && Math.abs(o.t - t) < h.P.dur + 1));
  const take = (h, t, v) => { const [a, b] = win(h.P, t), ph = phOf[Math.min(L, Math.max(0, t))]; const tot = sumIn(left, a, b, ph); if (tot <= 0) return 0; const c = Math.min(v, tot);
    for (let x = Math.max(0, Math.floor(a)); x < Math.min(L + 1, Math.ceil(b)); x++) if (phOf[x] === ph) left[x] -= left[x] * c / tot; return c; };
  // 3. the deadly moments: 10 s stretches where what normal healing can't cover is at least 40% of the worst one's
