  const sumIn = (a, b, ph) => { let s = 0; for (let t = Math.max(0, Math.floor(a)); t < Math.min(L + 1, Math.ceil(b)); t++) if (ph == null || phOf[t] === ph) s += d[t]; return s; };
  const srt = d.filter((v) => v > 0).slice().sort((a, b) => a - b), CAP = srt.length ? srt[Math.floor(srt.length * 0.94)] : 0;
  const MAG = NDZ_MAGIC[boss] || 0.85;
