  // (who has what: every healer and raid cooldown on the roster, with each healer's talent choice)
  const ents = []; for (const g of NDZ_BUFFS) if (g[0] === 'Healer cooldowns' || g[0] === 'Raid cooldowns') for (const x of g[2]) if (x[0] !== 'Devotion Aura') ents.push(x);
  const can = (p, x) => x[1].includes(p.cls) && (!x[2] || (p.specId ? x[2].includes(+p.specId) : p.role === 'healer' || x[2].length === 0));
  const have = []; const add = (who, n, id) => { const P = NDZ_CDPOW[n]; if (!P) return; have.push({ who, n, id, P, cd: ndzCdBack(n) || P.cd, used: [] }); };
  for (const p of pr.players.values()) for (const x of ents) if (can(p, x)) add(p.name, x[0], x[3]);
  for (const p of pr.players.values()) for (const [n, id] of NDZ_CDSPEC[+p.specId] || []) if (!have.some((h) => h.who === p.name && h.n === n)) add(p.name, n, id);
  for (const p of pr.players.values()) { const t = ndzTalOf(p.name, p.specId); if (!t) continue; const T = NDZ_TALC[+p.specId][1];
    for (let i = have.length - 1; i >= 0; i--) if (have[i].who === p.name && T.some((x) => x[0] === have[i].n || (x[0] === 'Restoral' && have[i].n === 'Revival'))) have.splice(i, 1);
    const id = (T.find((x) => x[0] === t.pick) || [])[1]; add(p.name, t.pick, id); }
  if (!have.length) return null;
  // 1-2. the big hits, ranked, each with its need
  const bigs = st.pk.map(([ph, rel, v, hit]) => { const p = PH.find((q) => q.ph === ph); return p ? { T: Math.round(p.s + rel), v, hit, ph: PH.indexOf(p), got: [] } : null; }).filter((x) => x && x.T <= L - 1);
  if (!bigs.length) return typeof ndzCdPlanV1 === 'function' ? ndzCdPlanV1(B, pr) : null;
  const byV = bigs.slice().sort((a, b) => b.v - a.v || a.T - b.T); byV.forEach((x, i) => { x.rank = i + 1; });
  const med = ((v) => v[Math.floor(v.length / 2)])(bigs.map((x) => x.v).sort((a, b) => a - b)) || 1;
  for (const x of bigs) x.need = x.v >= 2.5 * med ? 3 : x.v >= 1.5 * med ? 2 : 1;
  // 7. the fixed timing
  const lead = (h) => (h.P.k === 'back' ? -1 : h.P.k === 'heal' || h.P.k === 'hp' ? 1 : 2);
  const pressAt = (h, x) => { let t = Math.max(0, x.T - lead(h)); for (let k = 0; k < 6 && t < L && phOf[Math.min(L, t)] !== x.ph; k++) t++; return Math.max(0, Math.min(L - 1, t)); }; /* (into the hit's own phase, at most 6 s later, Oct 23) */
  const gapOk = (h, a, b) => { const lo = Math.min(a, b), hi = Math.max(a, b); return hi - lo >= h.cd + (phOf[Math.min(L, lo)] !== phOf[Math.min(L, hi)] ? 5 : 0); };
  const ready = (h, t) => h.used.every((u) => gapOk(h, u.t, t)) && (!NDZ_NOSTACK.has(h.n) || !rows0.some((r) => r.h !== h && r.h.n === h.n && Math.abs(r.t - t) < Math.max(8, h.P.dur || 0))); /* (the same cooldown from two players never overlaps: a second Rallying Cry inside the first adds nothing, Oct 24) */
  const rows0 = [], ordN = (r) => (r === 1 ? 'hardest' : r === 2 ? '2nd hardest' : r === 3 ? '3rd hardest' : r + 'th hardest');
  const place = (h, x, t, kind) => { const v = worth(h.P, t); h.used.push({ t, x }); if (x) x.got.push(h); rows0.push({ h, t, x, v, kind }); };
  // 3. the top raids' moments (lorrgs top 50 per spec, NDZ_CDHAB): each cooldown where most top players press it, the most agreed first
  const TD = (typeof NDZ_CDTOP === 'object' && NDZ_CDTOP[boss]) ? (NDZ_CDTOP[boss][B.diff] || NDZ_CDTOP[boss].Mythic || null) : null; /* (every boss, Mythic and Heroic, on our phases, Oct 24) */
  const HB = TD ? TD : ((typeof NDZ_CDHAB === 'object' && NDZ_CDHAB[boss]) || {}), habit = (n, T) => { let b = 0; for (const [ph, rel, sh] of HB[n] || []) { const p = PH.find((q) => q.ph === ph); if (p && Math.abs(p.s + rel - T) <= 10) b = Math.max(b, sh); } return b; };
  if (!Object.keys(HB).length) return ndzCdPlanClear(B, pr);
  const slotT = (ph, rel) => { const p = PH.find((q) => q.ph === ph); if (!p || rel > p.len + 5) return null; return Math.max(0, Math.round(p.s + Math.min(rel, Math.max(0, p.len - 2)))); };
  const near = (T, w) => bigs.filter((y) => Math.abs(y.T - T) <= (w || 8)).sort((p, q) => Math.abs(p.T - T) - Math.abs(q.T - T))[0] || null;
  const isThr = (h) => NDZ_ONCD.has(h.n), thr = have.filter(isThr), raid = have.filter((h) => !isThr(h));
  const slots = []; for (const n of new Set(have.map((h) => h.n))) for (const [ph, rel, sh] of HB[n] || []) { const T = slotT(ph, rel); if (T != null && T <= L - 1) slots.push({ n, T, sh }); }
  slots.sort((p, q) => q.sh - p.sh || p.T - q.T);
  const busy = (h, t) => rows0.some((r) => r.h.who === h.who && Math.abs(r.t - t) <= 5); /* (one player, two cooldowns within 5 s: only when nobody else can, Oct 24) */
  const readyBy = (h, T) => { for (let t = T; t <= Math.min(L - 1, T + 20); t++) if (ready(h, t)) return t; return null; }; /* (not back yet: up to 20 s later, since our kills are faster than theirs, Oct 24) */
  const topPass = (list) => { for (const sl of list) { if (rows0.some((r) => r.h.n === sl.n && Math.abs(r.t - sl.T) <= 8)) continue; const hs = have.filter((h) => h.n === sl.n).map((h) => [h, readyBy(h, sl.T)]).filter((q) => q[1] != null).sort((p, q) => (p[1] - sl.T) - (q[1] - sl.T) || busy(p[0], p[1]) - busy(q[0], q[1]) || p[0].used.length - q[0].used.length); if (!hs.length) continue;
    place(hs[0][0], near(hs[0][1]), hs[0][1], 'top'); rows0[rows0.length - 1].sh = sl.sh; rows0[rows0.length - 1].late = hs[0][1] - sl.T; } };
  topPass(slots.filter((q) => q.sh >= 0.5)); /* (what at least half of top players do, first; the rest after the bare hits, Oct 24) */
  // 4. where top raids stack big cooldowns: about as many of ours there, the strongest ready one filling in for any we don't have
  const MO = []; for (const [n, l] of Object.entries(HB)) { if (NDZ_ONCD.has(n) || n === 'Vampiric Embrace') continue; for (const [ph, rel, sh] of l) { const T = slotT(ph, rel); if (T == null || T > L - 1) continue; let m = MO.find((q) => Math.abs(q.T - T) <= 6); if (!m) { m = { T, w: 0, ns: [] }; MO.push(m); } m.w += sh; m.ns.push(n); } }
  const ourAt = (T) => rows0.filter((r) => !isThr(r.h) && Math.abs(r.t - T) <= 8);
  for (const m of MO.sort((p, q) => q.w - p.w)) { if (m.w < 1.5) continue; const want = Math.min(4, Math.round(m.w)); /* (only where top raids stack 2 or more, Oct 24) */ const x = near(m.T, 10);
    for (let k = 0; k < 4 && ourAt(m.T).length < want; k++) { const here = ourAt(m.T), c = raid.filter((h) => !here.some((r) => r.h.n === h.n)).map((h) => [h, x ? pressAt(h, x) : m.T]).filter(([h, t]) => ready(h, t) && t <= L - 1).sort((p, q) => busy(p[0], p[1]) - busy(q[0], q[1]) || worth(q[0].P, q[1]) - worth(p[0].P, p[1]))[0];
      if (!c) break; place(c[0], x, c[1], 'sub'); rows0[rows0.length - 1].m = m; } }
  // (the strongest first for the leftovers, with top raids' habits as a nudge)
