// NDZ_CDLEN: how long a cooldown lasts, by name: its buff's usual full length in those kills (so talents that lengthen it
// count), channels by their channel time, a few the logs rarely showed by their own text. Not here: CD_LEN, then none.
const NDZ_CDLEN = {"Avatar":20,"Colossus Smash":10,"Bladestorm":5,"Power Infusion":15,"Spell Reflection":5,"Rewind":4,"Divine Hymn":5,"Spirit Link Totem":6,"Die by the Sword":8,"Anti-Magic Zone":8,"Feint":6,"Vampiric Embrace":12,"Fade":10,"Angelic Feather":5,"Desperate Prayer":10,"Zephyr":8,"Hover":12,"Obsidian Scales":12,"Apotheosis":32,"Guardian Spirit":10,"Metamorphosis":9,"Summon Demonic Tyrant":20,"Dark Pact":5,"Unending Resolve":8,"Summon Darkglare":25,"Burning Rush":4,"Zenith":20,"Invoke Xuen, the White Tiger":20,"Celestial Conduit":4,"Berserking":12,"Fortifying Brew":15,"Touch of Karma":6,"Ascendance":15,"Astral Shift":12,"Spiritwalker's Grace":19,"Sprint":12,"Adrenaline Rush":15,"Crimson Vial":4,"Stormkeeper":4,"Empowering Venom":15,"Dragonrage":9,"Fiery Brand":12,"Demon Spikes":3,"Time Dilation":11,"Execution Sentence":10,"Avenging Wrath":24,"Divine Steed":5,"Divine Protection":8,"Blessing of Sacrifice":12,"Divine Shield":8,"Incarnation: Chosen of Elune":20,"Barkskin":12,"Dancing Rune Weapon":8,"Vampiric Blood":10,"Lichborne":12,"Death's Advance":10,"Anti-Magic Shell":7,"Icebound Fortitude":8,"Army of the Dead":30,"Dark Transformation":23,"Trueshot":17,"Survival of the Fittest":8,"Arcane Surge":18,"Prismatic Barrier":5,"Time Warp":40,"Ice Cold":6,"Piercing Howl":5,"Alter Time":5,"Rallying Cry":16,"Frenzied Regeneration":3,"Innervate":8,"Shadow Blades":16,"Shadow Dance":9,"Cloak of Shadows":5,"Aspect of the Cheetah":9,"Aspect of the Turtle":8,"Blur":10,"Pillar of Frost":12,"Breath of Sindragosa":28,"Tiger's Lust":6,"Blood Fury":15,"Stampeding Roar":8,"Dash":10,"Aura Mastery":8,"Bestial Wrath":15,"Mirror Image":15,"Soulburn":20,"Spirit Walk":8,"Earth Elemental":30,"Blessing of Freedom":8,"Evasion":10,"Sentinel":18,"Ardent Defender":12,"Guardian of Ancient Kings":8,"Wraith Walk":4,"Ghost Wolf":3,"Combustion":14,"Blazing Barrier":5,"Life Cocoon":12,"Fury of Xuen":12,"Convoke the Spirits":3,"Tranquility":6,"Doom Winds":10,"Invoke Yu'lon, the Jade Serpent":25,"Evangelism":24,"Ultimate Penitence":7,"Fury of Elune":8,"Blessing of Protection":10,"Nullsight":15,"Shield Block":16,"Shield Wall":8,"Ironbark":12,"Tiger Dash":5,"Lunar Beam":12,"Incarnation: Guardian of Ursoc":35,"Survival Instincts":6,"Pain Suppression":8,"Dispersion":6,"Fury of the Aspects":11,"Blessing of Spellwarding":10,"Unleash Life":10,"Invoke Niuzao, the Black Ox":25,"Blade Rush":5,"Ice Barrier":6,"Malevolence":20,"Summon Infernal":30,"Leap of Faith":4,"Roar of Sacrifice":10,"Recklessness":24,"Berserk":25,"Tiger's Fury":15,"Berserker Rage":6,"Takedown":10,"Aspect of the Eagle":15,"Heroism":40,"Avenging Crusader":23,"Bloodlust":40,"Harrier's Cry":40,"Celestial Alignment":15,"Tricks of the Trade":4,"Darkflight":10,"Misdirection":4,"Power Word: Barrier":10,"Darkness":8};
// ---- Big hits where the damage lands (Oct 22, your note: "there's no damage happening at that spot") ----
// The fastest kills' big hits are timed from the boss's cast; the raid's damage often lands a few seconds later, and a few barely hurt.
// Each big hit moves to the 2-second step of highest raid damage from its time to 6 s after (never earlier), and a big hit with
// nothing above 80% of the fight's average damage around it is dropped. Done once as the page loads, so the chart, the planner and
// the setup step all see the same times.
(() => { for (const [boss, byD] of Object.entries(NDZ_CDSTART)) for (const [diff, sd] of Object.entries(byD)) { const DG = (NDZ_TLDMG[boss] || {})[diff], dg = DG ? DG.ph || DG : null; if (!dg || !Array.isArray(sd.pk) || sd.pkSnap) continue;
  const all = Object.values(dg).flat().filter((v) => v > 0), avg = all.length ? all.reduce((a, b) => a + b, 0) / all.length : 0; if (!avg) continue;
  sd.pk = sd.pk.map(([ph, rel, v, hit]) => { const bins = dg[ph] || dg[String(ph)] || []; if (!bins.length) return [ph, rel, v, hit]; let bi = -1, bv = -1;
    for (let i = Math.max(0, Math.floor(rel / 2)); i <= Math.min(bins.length - 1, Math.floor((rel + 6) / 2)); i++) if (bins[i] > bv) { bv = bins[i]; bi = i; }
    if (bi < 0) return [ph, rel, v, hit]; if (bv < 0.8 * avg) return null; return [ph, Math.max(rel, bi * 2), v, hit]; }).filter(Boolean); sd.pkSnap = true; } })();
