// (everyone who raided with a team this tier, each with how many of its raid nights they were at; only this tier's raid bosses count)
function planTeamAll(g) { const nights = new Map(), all = new Set(), bs = new Set(planBosses());
  for (const v of HIST.mem.values()) if (pullGroups(v).includes(g.gid) && bs.has(v.boss)) { const k = nightOf(v.at); all.add(k); for (const n of v.players || []) { let x = nights.get(n); if (!x) nights.set(n, x = new Set()); x.add(k); } }
  const l = [...nights].map(([name, x]) => ({ name, n: x.size })).sort((a, b) => b.n - a.n || a.name.localeCompare(b.name)); return { list: l, nights: all.size }; }

// (a team's regulars: everyone at half or more of its raid nights this tier, 2 at least)
function planTeamRegs(g) { const T = planTeamAll(g), all = T.list.filter((x) => x.name && !/^Player-/.test(x.name)), need = T.nights < 2 ? T.nights : Math.max(2, Math.ceil(T.nights / 2));
  return { reg: all.filter((x) => x.n >= need).map((x) => String(x.name).split('-')[0]), others: all.filter((x) => x.n < need).length, need, nights: T.nights }; }
