  for (const c of cb) { const m = ca.find((x, i) => !used.has(i) && key(x) === key(c) && x.ph === c.ph && Math.abs(x.t - c.t) <= 2); if (m) { used.add(ca.indexOf(m)); continue; } const mv = ca.findIndex((x, i) => !used.has(i) && key(x) === key(c)); if (mv >= 0) { used.add(mv); mov.push({ c, from: ca[mv] }); } else add.push(c); }
  const drop = ca.filter((c, i) => !used.has(i));
