// (a call's line in the note: tag:everyone, its time, phase and kind)
function btlCallLine(lines, c) { for (let i = 0; i < lines.length; i++) { const m = /^\s*time:([\d.]+);ph:([\d.]+);(?:[^;]*;)*?tag:everyone;(?:[^;]*;)*?text:([^;]*);/i.exec(lines[i]); if (!m || +m[1] !== +c.t || +m[2] !== +c.ph) continue; const k = /^healthstone/i.test(m[3]) ? 'hs' : /^defensive/i.test(m[3]) ? 'def' : /^health ?potion/i.test(m[3]) ? 'pot' : ''; if (k === c.k) return i; } return -1; }
// (the phases end to end, in fight order, each its real length: the same as the whole-fight view)
