  const tally = () => new Map(), bump = (T, slot, n, did, rank) => { let s = T.get(slot); if (!s) T.set(slot, s = new Map()); let x = s.get(n); if (!x) s.set(n, x = { got: 0, of: 0, rank: [] }); x.of++; if (did) { x.got++; if (rank != null) x.rank.push(rank); } };
