  for (const x of on) if (x.rem) out.push('time:' + x.rem.time + ';ph:' + x.rem.ph + ';tag:' + x.rem.tag + (x.rem.id ? ';spellid:' + x.rem.id : '') + ';text:' + x.rem.text + ';');
