  "The Coiled Altar|H": { s: [2.6, 2.6, 2.6, 2.6, 3.8, 3.8, 4, 4.1, 4.7, 4.7, 4.7, 4.7], stop: 307, m: 0, k: 40 },
  "The Coiled Altar|M": { s: [2, 2, 2, 2, 2, 2, 2, 2, 3, 3, 3, 3, 3, 3, 3, 5, 5, 5, 6, 12, 12, 12], stop: 617, m: 0, k: 40 },
  "Entombed Sentinels|H": { s: [2.5, 2.5, 3.2, 3.2, 9.5, 13.3, 13.3, 13.3, 13.3], stop: 214, m: 0, k: 40 },
  "Entombed Sentinels|M": { s: [2, 2, 3, 3, 3, 3, 3, 5, 7, 12, 12, 12, 12], stop: 342, m: 0, k: 40 },
  "Vashnik the Malignant|H": { s: [1.1, 1.1, 2.4, 3.3, 3.3, 10, 10, 10], stop: 205, m: 0, k: 40 },
  "Vashnik the Malignant|M": { s: [1, 2, 2, 4, 4, 4, 5, 5, 14, 15, 15, 15, 15], stop: 353, m: 0, k: 40 },
  "Nek'zali the Soulcoiler|H": { s: [1.5, 1.9, 1.9, 1.9, 2.5, 9.1, 9.1, 9.1], stop: 209, m: 0, k: 40 },
