  "Ula'tek|H": { s: [0.9, 2.1, 2.5, 2.5, 2.5, 4.8, 4.8, 5, 5, 5, 5, 5, 7, 7.1, 7.1, 7.1, 7.1], stop: 454, m: 0, k: 40 },
  "Ula'tek|M": { s: [1, 1, 1, 1, 1, 1, 1, 2, 2, 3, 3, 3, 3, 4, 4, 6, 6, 8, 9, 9, 9], stop: 598, m: 0, k: 40 },
