  const shields = SH ? (r.bossAuras || []).filter((w) => w.n === SH.aura && w.a < end).map((w) => ({ a: w.a, e: Math.min(end, w.e == null ? end : w.e) })) : [];
  // (the raid's hardest 20 seconds, when it isn't already one of the windows above)
