    const say = W.length ? 'Our biggest 20 seconds of damage outside ' + (W.every((w) => w.kind === 'lust') ? 'Bloodlust' : W.every((w) => w.kind === 'amp') ? wn : 'those windows') : 'Our biggest 20 seconds of damage';
