    for (const row of s.rows || []) { const t = rowT(row); if (t != null) ts.push(t); } for (const g of s.groups || []) { if (g.t != null) ts.push(g.t); for (const row of g.rows || []) { const t = rowT(row); if (t != null) ts.push(t); } }
