    e.preventDefault();
    const [px, py] = toSvg(e), f = e.deltaY < 0 ? 1 / 1.15 : 1.15, nw = Math.min(Math.max(vb[2] * f, 40), Math.max(full[2] * 1.3, focus[2] * 1.3, +(svg.dataset.zmax || 0))), q = nw / vb[2];
