  const zc = (f) => { const cx = vb[0] + vb[2] / 2, cy = vb[1] + vb[3] / 2, nw = Math.min(Math.max(vb[2] * f, 40), Math.max(full[2] * 1.3, focus[2] * 1.3, +(svg.dataset.zmax || 0))); vb = [cx - nw / 2, cy - nw / 2, nw, nw]; apply(); };
