  const all = new Map(); for (const p of ps) { const a = p.dmgTS || []; for (let i = i0; i < Math.min(a.length, Math.ceil(w1)); i++) { const o = a[i]; if (o) for (const n in o) all.set(n, (all.get(n) || 0) + o[n]); } }
