  const rows = [...by.values()].filter((s) => s.tot >= 1).sort((a, b) => b.tot - a.tot), mx = rows.length ? rows[0].tot : 1, T0 = Math.max(1, tot);
  if (S.srcSel && !by.has(S.srcSel)) S.srcSel = null;
