  const l = [...ext].sort((a, b) => b[1] - a[1]), t = l.reduce((v, [, y]) => v + y, 0), f = (v) => (!mx ? C(v) : v >= mx ? (v / mx).toFixed(1) + ' bars' : (v / mx).toFixed(2) + ' of a bar');
