const TALENT_MAP = new Map();
function talentMap(cls) {
  if (TALENT_MAP.has(cls)) return TALENT_MAP.get(cls); const m = new Map();
  for (const x of String(TALENT_DATA[cls] || '').split('|')) { const [en, id, mx, ...nm] = x.split(':'); if (en) m.set(+en, { id: +id, max: +mx, name: nm.join(':') }); }
  // (an apex talent: one name over three or more nodes, each its own spell, e.g. Beacon of the Savior; its ranks add up)
  const ids = new Map(); for (const v of m.values()) { const o = ids.get(v.name) || { s: new Set(), max: 0 }; if (!o.s.has(v.id)) { o.s.add(v.id); o.max += v.max; } ids.set(v.name, o); }
  for (const v of m.values()) { const o = ids.get(v.name); v.apex = o.s.size >= 3; v.apexMax = o.max; }
  TALENT_MAP.set(cls, m); return m;
}
