  const nearTop = (c) => { if (c.st === 'bad' || top[c.k] == null) return false; const a = d.numV(c.v), b = d.numV(top[c.k]); if (a == null || b == null) return false; return (d.LOWB.test(c.k) ? a - b : b - a) < 5; }; /* (Oct 25) */
  const wrong = focus.filter((c) => !nearTop(c)).map((c) => ({ c, kd: c.st })).concat(gap.map((x) => ({ c: x.c, kd: 'gap' }))).slice(0, 3), right = good.slice(0, 2);
