  const clean = (t) => String(t || '').replace(/\s*\([^)]*\b(guides?|Wowhead|Icy Veins|SimulationCraft|Raidbots|Method)\b[^)]*\)/gi, '').replace(/\s+([.,])/g, '$1').trim();
