  const area = (pts, top, cls) => { if (!pts.length) return ''; let d = 'M' + pts[0][0].toFixed(1) + ',10', prev = null; for (const [t, v] of pts) { if (t > t1) break; const y = (10 - 10 * v / top).toFixed(2); d += ' L' + t.toFixed(1) + ',' + y; prev = y; } return '<path d="' + d + ' L' + t1.toFixed(1) + ',' + (prev || 10) + ' L' + t1.toFixed(1) + ',10 Z" class="' + cls + '"/>'; };
  const B = (n) => p.buffs.get(n), sp0 = (b) => (b ? b.sp.filter(([a]) => a <= t1).map(([a, e]) => [a, Math.min(e == null ? t1 : e, t1)]) : []);
