  const WT = { apl: 2, te: 1.5, som: 1, abc: 2, lfa: 1, ta: 3, ecl: 2.5, ecu: 2, db: 3, dbr: 2, dbec: 1.5, "p:Merithra's Blessing": 1.5, ess: 2.5, 'p:Essence Burst': 3, ebh: 2, stc: 2, inf: 1.5, 'cd:stasis': 2, 'cd:dream flight': 1.5, 'cd:tip the scales': 1, 'cd:rewind': 1, mana: 2 };
