  const stCombo = (q) => (flame ? q.got.filter((k) => k === 'dream breath').length >= 2 && q.got.includes('temporal anomaly') : q.got.includes('dream breath') && q.got.includes('temporal anomaly'));
  const goodSt = ['dream breath', 'temporal anomaly', 'emerald blossom', "merithra's blessing", 'echo', 'verdant embrace'];
