// one pull's cooldowns on its time line: Stasis from storing to release, Inner Flame, Merithra's Blessing and Essence Burst held as bars; Tip the Scales,
// Rewind, Temporal Anomaly and Dream Breath (gold at rank 1) as ticks; Essence and mana as levels; time ready long enough for a whole extra use in red
function pevkTimeline(x, s) {
  const { r, p, t1, end } = x, dur = Math.max(1, end), by = (n) => (((x.c.ab.find((y) => y.name.toLowerCase() === n.toLowerCase()) || {}).ts) || []).filter((t) => t <= t1);
  const dd = deadSpans(r, p).map(([a, b]) => '<rect x="' + a.toFixed(1) + '" y="0" width="' + Math.max(0, Math.min(dur, b) - a).toFixed(1) + '" height="10" class="tl-dd"/>').join('');
  const bars = (sp, cls) => sp.map(([a, c]) => '<rect x="' + a.toFixed(1) + '" y="2" width="' + Math.max(0.6, c - a).toFixed(1) + '" height="6" rx=".6" class="' + cls + '"/>').join('');
  const ticks = (ts, cls) => ts.map((t) => '<line x1="' + t.toFixed(2) + '" x2="' + t.toFixed(2) + '" y1="0.5" y2="9.5" class="tl-t' + (cls ? ' ' + cls : '') + '"/>').join('');
  const red = (l, cd) => (l || []).map(([a, b]) => '<rect x="' + a.toFixed(1) + '" y="0" width="' + Math.max(0.5, b - a).toFixed(1) + '" height="10" class="tl-rd' + (cd && b - a >= cd ? ' red' : '') + '"/>').join('');
  const row = (name, body, cls, label) => '<div class="tl-r' + (cls ? ' ' + cls : '') + '"><span class="tl-n">' + spellIcon(0, name) + '<span>' + esc(label || name) + '</span></span><svg viewBox="0 0 ' + dur + ' 10" preserveAspectRatio="none" aria-hidden="true">' + body + dd + '</svg></div>';
  const area = (pts, cls) => { if (!pts.length) return ''; let d = 'M' + pts[0][0].toFixed(1) + ',10', prev = null; for (const [t, v] of pts) { if (t > t1) break; const y = (10 - 10 * v).toFixed(2); d += ' L' + t.toFixed(1) + ',' + y; prev = y; } return '<path d="' + d + ' L' + t1.toFixed(1) + ',' + (prev || 10) + ' L' + t1.toFixed(1) + ',10 Z" class="' + cls + '"/>'; };
  const B = (n) => p.buffs.get(n), sp0 = (b) => (b ? b.sp.filter(([a]) => a <= t1).map(([a, e]) => [a, Math.min(e == null ? t1 : e, t1)]) : []);
  const st = B('Stasis (Store)'), sr = B('Stasis'), stasis = sp0(st).map(([a], i) => { const rel = sp0(sr)[i]; return [a, rel ? rel[1] : Math.min(t1, a + 30)]; });
  let h = '';
  if (stasis.length) h += row('Stasis', red((s.cdu.stasis || {}).capL, (s.cdu.stasis || {}).cd) + bars(stasis, 'tl-bv') + ticks(sp0(sr).map(([, e]) => e), 'ok'));
  const inf = sp0(B('Inner Flame')); if (inf.length) h += row('Inner Flame', bars(inf, 'tl-aw'));
  for (const n of ['Tip the Scales', 'Rewind', 'Dream Flight']) { const q = s.cdu[n.toLowerCase()]; if (by(n).length || q) h += row(n, red(q && q.capL, q && q.cd) + ticks(by(n), 'ok')); }
  if (by('Temporal Anomaly').length) h += row('Temporal Anomaly', red(s.m.ta) + ticks(by('Temporal Anomaly'), 'thin'));
  const emp = (p.empL || []).filter(([t, n]) => t <= t1 && n === 'Dream Breath'); if (by('Dream Breath').length) h += row('Dream Breath', red(s.m.db) + ticks(emp.filter(([, , l]) => l === 1).map(([t]) => t), 'ok') + ticks(emp.filter(([, , l]) => l !== 1).map(([t]) => t), 'warn') + ticks(by('Dream Breath').filter((t) => !emp.some(([u]) => u >= t && u - t <= 4)), 'thin'));
  const mb = sp0(B("Merithra's Blessing")); if (mb.length) h += row("Merithra's Blessing", bars(mb, 'tl-io'), '', "Merithra's Blessing held");
  const eb = sp0(B('Essence Burst')); if (eb.length) h += row('Essence Burst', bars(eb, 'tl-io'), '', 'Essence Burst held');
  const ess = ((p.res.get('19') || { pts: [] }).pts).filter(([t]) => t <= t1).map(([t, c, m]) => [t, m ? c / m : 0]); if (ess.length > 1) h += row('Essence Burst', area(ess, 'tl-hpa'), 'tl-lv', 'Essence');
  if (s.mnL && s.mnL.length > 1) h += row('Mana', area(s.mnL, 'tl-mna'), 'tl-lv', 'Mana');
  const R2 = (v) => Math.round(v * 100) / 100, sp2 = (l) => l.map(([a, b]) => [R2(a), R2(b)]);
  const ev = { dur: R2(dur), ev: x.c.ab.flatMap((a) => a.ts.filter((t) => t <= t1).map((t) => [R2(t), a.name, a.id])).sort((u, w) => u[0] - w[0]), dd: sp2(deadSpans(r, p)),
    st: [['Stasis storing or held', sp2(stasis)], ['Inner Flame up', sp2(inf)], ["Merithra's Blessing held", sp2(mb)], ['Essence Burst held', sp2(eb)]].filter((y) => y[1].length),
    lv: [['Essence', ((p.res.get('19') || { pts: [] }).pts).filter(([t]) => t <= t1).map(([t, c]) => [R2(t), c])]],
    mn: (s.mnL || []).filter((y, i, l) => !i || i === l.length - 1 || Math.abs(y[1] - l[i - 1][1]) > 0.004 || y[0] - l[i - 1][0] > 3).map(([t, v]) => [R2(t), Math.round(1000 * v) / 1000]) };
  const step = dur > 400 || (document.documentElement.clientWidth || 1000) < 700 ? 60 : 30, ax = []; for (let t = 0; t <= dur; t += step) ax.push('<span style="left:' + (100 * t / dur).toFixed(2) + '%">' + T(t) + '</span>');
  return '<div class="spc-tl" data-ev="' + esc(JSON.stringify(ev)) + '">' + h + '<div class="tl-ax"><div>' + ax.join('') + '</div></div><div class="tl-lg"><span><i class="bv"></i>Stasis, storing to release</span><span><i class="aw"></i>Inner Flame</span><span><i class="ok"></i>Pressed, or Dream Breath at rank 1</span><span><i class="warn"></i>Dream Breath at a higher rank</span><span><i class="io"></i>A proc held</span><span><i class="hp"></i>Essence</span><span><i class="mn"></i>Mana</span><span><i class="red"></i>Ready for a whole extra use</span>' + (t1 < end - 0.5 ? '<span><i class="dd"></i>Dead</span>' : '') + '</div><div class="tl-hv" hidden></div><div class="tl-tip" hidden></div></div>';
}
// ---- Demonology Warlock: what each player did with their demons. From the Midnight guides (Wowhead, Icy Veins), WoWAnalyzer's Demonology module
// and SimulationCraft's action list (the one Raidbots sims with). Per pull:
//  - Casting: always be casting, cast bars counted (Shadow Bolt, Hand of Gul'dan, Infernal Bolt, a Demonbolt without a Demonic Core).
//  - Demonic Tyrant: on cooldown, and each window (Dominion of Argus's 25 s, or the Tyrant's own 20): Hand of Gul'dans in it, Dreadstalkers out
//    (cast in the 12 s before), Demonic Cores held (2 or more; not the opener's), Soul Shards left at its end (each 3 a Hand of Gul'dan missed), the
//    demons it empowered (Demonic Power's top stack on the Tyrant), and your damage in it, your demons' included.
//  - Soul Shards: wasted (the log's own waste on each gain), where they came from and what spent them; their level through the pull.
//  - Demonic Core: each one spent on a Demonbolt, or lost (a new one at 4 stacks, or run out); Demonbolt without one.
//  - Cooldowns: Call Dreadstalkers, the Grimoires, Summon Doomguard, Power Siphon; Implosion with 6 Wild Imps (its hits on the target it hit most).
//  - The hero tree's procs (Diabolist: Ruination, Infernal Bolt, Demonic Art), spent or run out.
const PDEM_CD = { 'summon demonic tyrant': 60, 'call dreadstalkers': 20, 'grimoire: imp lord': 120, 'grimoire: fel ravager': 120, 'summon doomguard': 120, 'power siphon': 30 };
const PDEM_PROC = [{ n: 'Ruination', use: ['ruination'] }, { n: 'Infernal Bolt', use: ['infernal bolt'] }, { n: 'Demonic Art: Overlord', use: ["hand of gul'dan", 'ruination'], g: 'Demonic Art' },
  { n: 'Demonic Art: Mother of Chaos', use: ["hand of gul'dan", 'ruination'], g: 'Demonic Art' }, { n: 'Demonic Art: Pit Lord', use: ["hand of gul'dan", 'ruination'], g: 'Demonic Art' }];
// (the scales, eased to what the top players on Mythic do)
const PDEM_K = { abcOk: 0.77, abcW: 0.68, hogOk: 8, hogW: 6, sswOk: 0.04, sswW: 0.1, drOk: 0.85, drW: 0.7 };
// (Demonology's own "Next time" for each line, by its key)
