  const dd = deadSpans(r, p).map(([a, b]) => '<rect x="' + a.toFixed(1) + '" y="0" width="' + Math.max(0, Math.min(dur, b == null ? dur : b) - a).toFixed(1) + '" height="10" class="tl-dd"/>').join('');
  const bars = (sp, cls) => sp.map(([a, c]) => '<rect x="' + a.toFixed(1) + '" y="2" width="' + Math.max(0.6, c - a).toFixed(1) + '" height="6" rx=".6" class="' + cls + '"/>').join('');
  const ticks = (ts, cls) => ts.map((t) => '<line x1="' + t.toFixed(2) + '" x2="' + t.toFixed(2) + '" y1="0.5" y2="9.5" class="tl-t' + (cls ? ' ' + cls : '') + '"/>').join('');
  const red = (q) => (q && q.capL || []).map(([a, b]) => '<rect x="' + a.toFixed(1) + '" y="0" width="' + Math.max(0.5, b - a).toFixed(1) + '" height="10" class="tl-rd' + (b - a >= q.cd ? ' red' : '') + '"/>').join('');
