  const win = (s.ty || []).map((q) => [q.t, q.e]); let h = '';
  h += row('Summon Demonic Tyrant', red(s.cdu['summon demonic tyrant']) + bars(win, 'tl-bv') + ticks(by('Summon Demonic Tyrant'), 'ok'), '', doa ? 'Tyrant (Dominion of Argus)' : 'Demonic Tyrant');
  if (by('Call Dreadstalkers').length || s.cdu['call dreadstalkers']) h += row('Call Dreadstalkers', red(s.cdu['call dreadstalkers']) + ticks(by('Call Dreadstalkers'), 'ok'));
  for (const n of ['Grimoire: Imp Lord', 'Grimoire: Fel Ravager', 'Summon Doomguard', 'Power Siphon']) { const q = s.cdu[n.toLowerCase()]; if (by(n).length || q) h += row(n, red(q) + ticks(by(n), 'ok')); }
  if (by("Hand of Gul'dan").length) h += row("Hand of Gul'dan", ticks(by("Hand of Gul'dan"), 'thin') + ticks(by('Ruination'), 'ok'), '', by('Ruination').length ? "Hand of Gul'dan, Ruination" : "Hand of Gul'dan");
  if ((s.imp || []).length) h += row('Implosion', ticks(s.imp.filter((q) => q.n >= 6).map((q) => q.t), 'ok') + ticks(s.imp.filter((q) => q.n < 6).map((q) => q.t), 'warn'));
  if (by('Demonbolt').length) { const hard = new Set(s.m.dbh || []); h += row('Demonbolt', ticks(by('Demonbolt').filter((t) => !hard.has(t)), 'thin') + ticks([...hard], 'warn')); }
  if (s.dcL && s.dcL.length > 1) h += row('Demonic Core', area(s.dcL, 4, 'tl-hpa'), 'tl-lv', 'Demonic Cores');
  if (s.ssL && s.ssL.length > 1) h += row('Soul Shard', area(s.ssL, 5, 'tl-mna'), 'tl-lv', 'Soul Shards');
