function aplWhere(log, wins, len, WIN, res) {
  const L = Math.max(1, len), X = (t) => (100 * Math.min(1, Math.max(0, t / L))).toFixed(2), bad = log.filter((y) => !y[1]), inW = (t) => (wins || []).some((w) => t >= w.t && t <= w.e), nIn = bad.filter((y) => inW(y[0])).length, rn = res ? res.nl || res.n : '';
  const strip = '<div class="spc-ast">' + (wins || []).map((w) => '<em style="left:' + X(w.t) + '%;width:' + (100 * (w.e - w.t) / L).toFixed(2) + '%"></em>').join('') + log.map((y) => '<i class="' + (y[1] ? 'ok' : 'no') + '" style="left:' + X(y[0]) + '%"' + (y[1] ? '' : ' title="' + esc(T(y[0]) + ': you pressed ' + y[2] + ', the list wanted ' + y[3]) + '"') + '></i>').join('') + '</div>' +
    '<div class="spc-asx"><span>0:00</span><span>' + T(L / 2) + '</span><span>' + T(L) + '</span></div>';
  const sum = '<p class="spc-asm">' + (bad.length ? bad.length + (bad.length === 1 ? ' slip' : ' slips') + ' in ' + log.length + ' casts' + (WIN && (wins || []).length ? ' · ' + nIn + ' in ' + WIN.n : '') : 'No slips in ' + log.length + ' casts.') + '</p><p class="slv-lg no-ic"><span><i class="ok"></i>Right press</span><span><i class="no"></i>Slip</span>' + (WIN && (wins || []).length ? '<span><i class="win"></i>' + esc(WIN.n) + '</span>' : '') + '</p>';
  const g = new Map(); for (const y of bad) { const kk = y[2] + '|' + y[3] + '|' + y[4]; if (!g.has(kk)) g.set(kk, []); g.get(kk).push(y); }
  const ctx = (y) => [y[6] != null && rn ? rn + ' ' + y[6] : '', y[5].length ? y[5].join(', ') + ' up' : '', inW(y[0]) && WIN ? 'in ' + WIN.n : ''].filter(Boolean).join(' · ');
  const rowsH = [...g.values()].sort((u, v) => v.length - u.length).slice(0, 8).map((l) => { const e = { did: l[0][2], want: l[0][3], why: l[0][4] }, cnt = new Map(); for (const y of l) for (const b of y[5]) cnt.set(b, (cnt.get(b) || 0) + 1);
    const common = [...cnt].filter(([b, v]) => v >= l.length / 2 && !String(e.why).includes(b)).map(([b]) => b), rv = l.map((y) => y[6]).filter((v) => v != null), avR = rv.length ? Math.round(rv.reduce((v, x) => v + x, 0) / rv.length) : null;
    const usual = [common.length ? andL(common) + ' up' : '', avR != null && rn ? 'about ' + avR + ' ' + rn : ''].filter(Boolean);
    const why = aplWhy(e), mx = Math.max(...[...g.values()].map((z) => z.length));
    return '<div class="spc-slr slv-row no-ic"' + (usual.length ? ' title="' + esc('Usually with ' + usual.join(' and ') + '.') + '"' : '') + '>' + aplPair(e.did, e.want) + '<span class="slv-why">' + esc(why) + '</span>' +
      '<span class="slv-n"><b>' + l.length + '×</b><span class="slv-bar"><i style="width:' + Math.round(100 * l.length / mx) + '%"></i></span></span>' +
      '<span class="spc-slt">' + l.map((y) => '<button type="button" class="spc-sltc' + (inW(y[0]) ? ' in' : '') + '" data-mt="' + y[0].toFixed(2) + '" title="' + esc(ctx(y) || T(y[0])) + '">' + T(y[0]) + '</button>').join('') + '</span></div>'; }).join('');
  return strip + sum + (rowsH ? '<div class="spc-slp">' + rowsH + '</div>' : '');
}
