    const area = '<svg class="cmp-cdt-a" viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="none"><polygon points="0,' + H + ' ' + pts + ' ' + (W * l.end / mxE).toFixed(1) + ',' + H + '" /></svg>';
