  // a player's build in a few words, from their talent names and hero tree
  build(has, hero) {
    const virtue = has('Beacon of Virtue'), faith = has('Beacon of Faith'), hl = ['Divine Favor', 'Hand of Divinity', 'Resplendent Light', 'Divine Overload'].filter(has).length;
    const extra = [virtue ? 'Beacon of Virtue' : faith ? 'Beacon of Faith' : '', has('Avenging Crusader') ? 'Avenging Crusader' : '', has('Holy Prism') && !has('Divine Toll') ? 'Holy Prism' : ''].filter(Boolean);
    const style = has('Avenging Crusader') ? 'built around Judgment and melee' : faith || hl >= 2 ? 'built around Holy Light (more Holy Light, no Beacon of Virtue to cast)' : virtue ? 'built for burst healing into 5 Beacons' : '';
    return { key: (virtue ? 'V' : faith ? 'F' : '') + (has('Avenging Crusader') ? 'C' : '') + (hero || ''), name: (hero || 'Holy Paladin') + (extra.length ? ' with ' + extra.join(' and ') : ''), style, guide: this.guide[virtue ? 'Beacon of Virtue' : 'Beacon of Faith'] };
  },
