  const mv = data.filter((a) => mvp.has(a.p.name)).sort((u, v) => ['tank', 'healer', 'dps'].indexOf(u.p.role || 'dps') - ['tank', 'healer', 'dps'].indexOf(v.p.role || 'dps') || v.score - u.score);
