  const follow = () => { cancelAnimationFrame(raf); raf = requestAnimationFrame(place); };
  const finish = (seen) => { if (seen !== false) store.set(TIPS_KEY(k), '1'); removeEventListener('scroll', follow, true); removeEventListener('resize', follow); document.removeEventListener('keydown', key, true); ov.classList.add('out'); setTimeout(() => ov.remove(), 220); };
  const draw = () => { const s = steps[i], last = i === steps.length - 1, e = tipVis(s.sel);
    bub.innerHTML = '<div class="pt-k">' + (i + 1) + ' of ' + steps.length + '</div><b>' + esc(s.t) + '</b><p>' + esc(s.p) + '</p><div class="pt-nav">' + (i ? '<button class="btn" data-p="back" type="button">Back</button>' : '<button class="linkbtn pt-tour" data-p="tour" type="button">Take the tour</button>') +
      '<button class="btn primary" data-p="' + (last ? 'done' : 'next') + '" type="button">' + (last ? 'Got it' : 'Next') + '</button></div>';
    bub.querySelectorAll('[data-p]').forEach((b) => (b.onclick = () => { const a = b.dataset.p; if (a === 'next') { i++; draw(); } else if (a === 'back') { i--; draw(); } else if (a === 'tour') { finish(); startTour(0); } else finish(); }));
    bub.classList.remove('in'); void bub.offsetWidth; bub.classList.add('in');
    if (e) { const b = e.getBoundingClientRect();
      // (taller than most of the screen, like the debrief on a phone: its top comes into view, below the tabs)
      if (b.height > innerHeight * 0.6) { e.style.scrollMarginTop = '150px'; e.scrollIntoView({ block: 'start' }); } else if (b.top < 70 || b.bottom > innerHeight - 40) e.scrollIntoView({ block: 'center' }); }
    place(); const f = bub.querySelector('.btn.primary'); if (f) f.focus(); };
  // (Enter or → for next, ← for back; Escape doesn't skip it)
  const key = (e) => { if (!document.body.contains(ov)) return; if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); } else if (e.key === 'ArrowRight' && i < steps.length - 1) { i++; draw(); } else if (e.key === 'ArrowLeft' && i > 0) { i--; draw(); } };
  addEventListener('scroll', follow, true); addEventListener('resize', follow); document.addEventListener('keydown', key, true);
