  if (el) { el.classList.add('out'); document.body.classList.remove('touring'); setTimeout(() => el.remove(), 260); }
  if (!popped && history.state && history.state.gs) { let ran = false; GS_POP = () => { if (ran) return; ran = true; GS_POP = null; if (then) then(); };
    try { history.back(); } catch (e) { /* ignore */ } setTimeout(() => { if (GS_POP) GS_POP(); }, 700); return; }
