  const line = (x) => '<div class="ps-l"><span class="nm" style="color:' + x.col + '">' + esc(x.n) + '</span><span class="ps-g">' + gradeChip(letterOf(x.was)) + '<span class="sub">→</span>' + gradeChip(letterOf(x.v)) + '</span>' + plTr(x.d) + '</div>';
