  svg.addEventListener('pointermove', (e) => { if (!drag) return; const r = svg.getBoundingClientRect(), v = drag.v; set(v[0] - (e.clientX - drag.x) * v[2] / r.width, v[1] - (e.clientY - drag.y) * v[3] / r.height, v[2]); });
